css='''<style id="bioprecis-11-css">
:focus-visible{outline:3px solid var(--cyan);outline-offset:3px}.skip-link{position:fixed;left:10px;top:-60px;z-index:999;background:var(--cyan);color:#04242c;padding:10px 14px;border-radius:10px;font-weight:900}.skip-link:focus{top:10px}.scenario-tag{display:inline-flex;margin-left:5px;padding:2px 6px;border-radius:999px;border:1px solid rgba(255,211,106,.38);background:rgba(255,211,106,.08);color:#ffe29a;font-size:9px;font-weight:800;vertical-align:middle}.demo-banner{display:flex;gap:10px;align-items:flex-start;padding:12px 14px;margin-bottom:14px;border-radius:14px;background:rgba(255,211,106,.08);border:1px solid rgba(255,211,106,.28);color:#ffe8aa;font-size:12px;line-height:1.55}.demo-banner b{white-space:nowrap}.mobile-menu-btn{display:none;position:fixed;z-index:260;left:14px;bottom:16px;width:50px;height:50px;border-radius:16px;border:1px solid #397789;background:#0b3a4a;color:#fff;font-size:23px;box-shadow:0 14px 38px rgba(0,0,0,.36)}.module-note{margin-top:9px;padding:9px 10px;border-radius:10px;background:rgba(99,240,242,.055);border:1px solid rgba(99,240,242,.14);color:var(--muted);font-size:11px;line-height:1.5}.institutional-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:12px}.institutional-grid .card h3{color:var(--cyan);margin-top:0}.roadmap{display:grid;gap:8px}.roadmap .item{position:relative;padding-left:17px}.roadmap .item:before{content:"";position:absolute;left:5px;top:16px;width:6px;height:6px;border-radius:50%;background:var(--cyan)}
@media(max-width:1120px){.mobile-menu-btn{display:block}.side{position:fixed!important;left:-292px;top:0;width:280px;height:100vh!important;transition:left .3s ease;box-shadow:18px 0 50px rgba(0,0,0,.4);z-index:250}.side.mobile-open{left:0}.shell{grid-template-columns:1fr!important}.nav{display:grid!important;overflow:visible!important}.institutional-grid{grid-template-columns:1fr}}
@media(prefers-reduced-motion:reduce){*,*:before,*:after{animation-duration:.001ms!important;animation-iteration-count:1!important;scroll-behavior:auto!important;transition-duration:.001ms!important}}
@media print{.side,.topbar,.mobile-menu-btn,.splash,.login-modal,.actions{display:none!important}.shell{display:block}.page{display:none!important}#reports.page{display:block!important}body{background:white!important;color:#111!important}.card{box-shadow:none!important;background:white!important;color:#111!important;border-color:#bbb!important}.muted{color:#444!important}}
</style>'''
