about='''<section class="page" id="about"><div class="card explain"><h3>Sobre a BIOPRECIS</h3><p>Visão institucional do projeto, problema, solução, estágio atual e próximos marcos.</p></div><div class="institutional-grid" style="margin-top:14px"><div class="card"><h3>Problema</h3><p class="bio">Dados biológicos costumam ficar fragmentados entre exames, sistemas, camadas ômicas e fontes científicas, dificultando uma leitura integrada para pesquisa.</p></div><div class="card"><h3>Solução BIOPRECIS</h3><p class="bio">Uma plataforma que organiza, integra e visualiza dados biológicos, simulações multiômicas, gêmeo digital, IA contextual, relatórios e fluxos laboratoriais.</p></div><div class="card"><h3>Público-alvo</h3><p class="bio">Pesquisadores, universidades, laboratórios, empresas de biotecnologia e, futuramente, instituições de saúde em contextos validados e regulados.</p></div></div><div class="grid two" style="margin-top:14px"><div class="card"><h2>Missão</h2><p class="bio">Integrar biologia, inteligência artificial e ciência de dados em apoio à pesquisa e à inovação científica.</p><h2>Visão</h2><p class="bio">Evoluir de um MVP demonstrativo para uma plataforma validada, segura e interoperável de biotecnologia de precisão.</p><h2>Valores</h2><div class="chips"><span class="chip">Inovação científica</span><span class="chip">Ética</span><span class="chip">Precisão</span><span class="chip">Segurança</span><span class="chip">Transparência</span><span class="chip">IA responsável</span></div></div><div class="card"><h2>Estágio atual e próximos marcos</h2><div class="roadmap"><div class="item"><b>Agora — MVP público</b><br><span class="muted">Interface interativa, simulações e demonstrações sintéticas.</span></div><div class="item"><b>Próximo — Backend seguro</b><br><span class="muted">Autenticação real, banco de dados, APIs e governança.</span></div><div class="item"><b>Depois — Validação científica</b><br><span class="muted">Estudos, métricas de desempenho, documentação e revisão técnica.</span></div><div class="item"><b>Expansão — Parcerias</b><br><span class="muted">Universidades, laboratórios e empresas de biotecnologia.</span></div></div><div class="module-note"><b>Buscamos:</b> colaboração científica, validação técnica e conexões para desenvolvimento responsável.</div></div></div></section>'''
html=re.sub(r'<section class="page" id="about">.*?</section>',about,html,count=1,flags=re.S)

js='''<script id="bioprecis-11-js">(function(){const KEY='bioprecis_mvp_state_v11';window.toggleMobileMenu=function(){document.querySelector('.side')?.classList.toggle('mobile-open')};const oldGo=window.go;if(typeof oldGo==='function')window.go=function(id){oldGo(id);try{localStorage.setItem('bioprecis_last_page',id)}catch(e){}document.querySelector('.side')?.classList.remove('mobile-open')};const oldTheme=window.toggleTheme;if(typeof oldTheme==='function')window.toggleTheme=function(){oldTheme();try{localStorage.setItem('bioprecis_theme',document.documentElement.classList.contains('light')?'light':'dark')}catch(e){}};window.bpSaveState=function(){try{localStorage.setItem(KEY,JSON.stringify({twin:{immune:document.getElementById('immune')?.value,micro:document.getElementById('micro')?.value,metab:document.getElementById('metab')?.value,inflam:document.getElementById('inflam')?.value}}))}catch(e){}};window.exportExcel=function(){const rows=[['Amostra','Equilíbrio','Imunidade','Microbioma','Metabolismo','Inflamação'],[document.getElementById('reportSample').value,document.getElementById('balance').textContent,document.getElementById('immune').value,document.getElementById('micro').value,document.getElementById('metab').value,document.getElementById('inflam').value]];const csv='\\ufeff'+rows.map(r=>r.map(v=>'"'+String(v).replace(/"/g,'""')+'"').join(';')).join('\\n');const blob=new Blob([csv],{type:'text/csv;charset=utf-8'}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='bioprecis_relatorio.csv';a.click()};const oldGenerate=window.generateReport;window.generateReport=function(){if(typeof oldGenerate==='function')oldGenerate();const q=document.getElementById('reportPreview');if(q)q.insertAdjacentHTML('beforeend','<p class="module-note"><b>Aviso:</b> relatório demonstrativo com dados sintéticos; não é laudo, diagnóstico ou prescrição.</p>')};document.addEventListener('DOMContentLoaded',()=>{document.querySelectorAll('.nav button').forEach(b=>{b.setAttribute('aria-label','Abrir módulo '+b.textContent.trim());b.addEventListener('click',()=>document.querySelector('.side')?.classList.remove('mobile-open'))});try{if(localStorage.getItem('bioprecis_theme')==='light')document.documentElement.classList.add('light');const s=JSON.parse(localStorage.getItem(KEY)||'null');if(s?.twin){for(const k of ['immune','micro','metab','inflam']){const e=document.getElementById(k);if(e&&s.twin[k]!=null)e.value=s.twin[k]}if(typeof window.updateTwin==='function')window.updateTwin(false)}const pg=localStorage.getItem('bioprecis_last_page');if(pg&&document.getElementById(pg)&&typeof window.go==='function')window.go(pg)}catch(e){}['immune','micro','metab','inflam'].forEach(id=>document.getElementById(id)?.addEventListener('change',bpSaveState))})})();</script>'''
if 'bioprecis-11-js' not in html: html=html.replace('</body>',js+'\n</body>',1)

